import {GEAR_ITEMS,GEAR_TRAITS,gearPool,gearSlotOpen,gearRollCost,gearUpgradeCost,gearTraitText} from './gear.js';
import {MATERIALS} from './materials.js';
import {gemIcon} from './expedition-map.js';
import {glyph} from './ui-art.js';
import {generateAsset,assetSvgBody} from './art-kit.js';
const fmt=n=>new Intl.NumberFormat('pt-BR').format(n);
const item=id=>GEAR_ITEMS.find(x=>x.id===id);
export function gearMarkup(s,piece='pickaxe',index=0,kind=1,busy=false,confirmClear=false){
 const gear=s.forge.gear,chosen=item(piece)||GEAR_ITEMS.at(-1),equipped=gear.items[chosen.id],slot=equipped.traits[index]||null,color=chosen.colors.includes(kind)?kind:chosen.colors[0],pending=gear.pending,roll=gearRollCost(s,chosen.id,index,color),upgrade=gearUpgradeCost(s,chosen.id,index),locked=!gearSlotOpen(s,index);
 const portrait='<svg viewBox="0 0 100 110" role="img" aria-label="Equipamento do minerador">'+assetSvgBody(generateAsset('miner',{variant:Math.min(3,Math.ceil(s.forge.levels.armor/34))}))+'</svg>';
 const pieceButtons=GEAR_ITEMS.map(g=>{const p=gear.items[g.id],filled=p.traits.filter(Boolean).length;return '<button data-gear-piece="'+g.id+'" aria-pressed="'+(g.id===chosen.id)+'">'+glyph(g.icon)+'<span><strong>'+g.name.toUpperCase()+'</strong><small>'+filled+' / '+(gearSlotOpen(s,1)?2:1)+' ATRIBUTOS</small></span></button>';}).join('');
 const traitButtons=equipped.traits.map((t,i)=>'<button data-gear-slot="'+i+'" aria-pressed="'+(index===i)+'" '+(!gearSlotOpen(s,i)?'disabled':'')+'><b>'+(i+1)+'</b><span><strong>'+(t?GEAR_TRAITS.find(x=>x.id===t.id).name:gearSlotOpen(s,i)?'VAZIO':'BLOQUEADO')+'</strong><small>'+(!gearSlotOpen(s,i)?'FORJA NV. 20':(t?gearTraitText(t):''))+'</small></span></button>').join('');
 const colorButtons=chosen.colors.map(k=>'<button data-gear-kind="'+k+'" aria-pressed="'+(color===k)+'" style="--mineral:'+MATERIALS[k].color+'">'+gemIcon(k)+'<strong>'+MATERIALS[k].name.toUpperCase()+'</strong></button>').join('');
 const possible=gearPool(chosen.id,color).map(t=>'<span>'+t.label+'</span>').join('');
 const offers=pending?'<div class="gear-offers"><h5>ESCOLHA UM ATRIBUTO</h5><span class="gear-current">ATUAL · '+gearTraitText(slot)+'</span><div>'+pending.options.map((o,i)=>{const def=GEAR_TRAITS.find(t=>t.id===o.id);return '<button data-gear-offer="'+i+'" style="--mineral:'+MATERIALS[o.kind].color+'"><b>'+def.name.toUpperCase()+'</b><strong>'+gearTraitText(o)+'</strong><small>'+(o.rank>1?'RARO · NV. 2':'NV. 1')+'</small></button>';}).join('')+'</div><button class="gear-keep" id="gearKeep">MANTER ATUAL</button></div>':
 '<div class="gear-actions">'+(slot?'<div class="gear-equipped"><strong>'+GEAR_TRAITS.find(t=>t.id===slot.id).name.toUpperCase()+' · NV. '+slot.rank+'/'+(GEAR_TRAITS.find(t=>t.id===slot.id).maxRank||10)+'</strong><span>'+gearTraitText(slot)+'</span></div>':'')+
 (upgrade?'<button class="gear-upgrade primary" id="gearUpgrade" '+(busy||s.materials[upgrade.kind]<upgrade.crystals||s.bank<upgrade.coins?'disabled':'')+'>APRIMORAR · '+Math.round(upgrade.chance*100)+'%<small>'+fmt(upgrade.crystals)+' '+MATERIALS[upgrade.kind].name.toUpperCase()+' · ◇ '+fmt(upgrade.coins)+'</small></button>':slot?'<b class="gear-max">ATRIBUTO MÁXIMO</b>':'')+
 '<button class="gear-roll secondary" id="gearRoll" '+(busy||locked||!roll||s.materials[color]<roll.crystals||s.bank<roll.coins?'disabled':'')+'>'+(slot?'ROLETAR OUTRO':'ROLETAR ATRIBUTO')+'<small>'+(roll?fmt(roll.crystals)+' '+MATERIALS[color].name.toUpperCase()+' · ◇ '+fmt(roll.coins):locked?'FORJA NV. 20':'SEM OUTROS ATRIBUTOS')+'</small></button>'+
 (slot?'<button class="gear-clear" id="gearClear" '+(busy?'disabled':'')+'>'+(confirmClear?'CONFIRMAR LIMPEZA':'LIMPAR ATRIBUTO')+'</button>':'')+'</div>';
 return '<section class="gear-workbench"><header><h4>EQUIPAMENTO</h4><b>UMA PEÇA DE CADA</b></header><div class="gear-layout"><div class="gear-portrait">'+portrait+'</div><div class="gear-pieces">'+pieceButtons+'</div></div><div class="gear-focus"><h5>'+glyph(chosen.icon)+chosen.name.toUpperCase()+'</h5><b>PODER '+equipped.traits.reduce((n,t)=>n+(t?.rank||0),0)+' · TENSÃO '+equipped.strain+'</b></div><div class="gear-traits">'+traitButtons+'</div><div class="gear-colors">'+colorButtons+'</div><div class="gear-possible"><b>'+MATERIALS[color].name.toUpperCase()+' PODE DAR</b><div>'+possible+'</div></div>'+offers+'</section>';
}
